    "solution": "Step 1: Let tens digit be \\(x\\) and units digit be \\(y\\). The number is \\(10x + y\\).\nStep 2: Equation 1: \\(x + y = 12\\). Reversing digits gives \\(10y + x\\).\nStep 3: Equation 2: \\((10x + y) - (10y + x) = 36 \\implies 9(x - y) = 36 \\implies x - y = 4\\).\nAdding gives \\(2x = 16 \\implies x = 8\\) and \\(y = 4\\). The number is \\(84\\).",
