    "options": [
      {
        "text": "\\(9(x - y)\\)",
        "isCorrect": true
      },
      {
        "text": "\\(11(x + y)\\)",
        "isCorrect": false
      },
      {
        "text": "\\(9(x + y)\\)",
        "isCorrect": false
      },
      {
        "text": "\\(x - y\\)",
        "isCorrect": false
      }
    ],
    "correctAnswer": "A",
    "solution": "Step 1: Compute difference: \\((10x + y) - (10y + x)\\).\nStep 2: Collect like terms: \\(10x - x + y - 10y = 9x - 9y\\).\nStep 3: Factor out 9: \\(9(x - y)\\).",
