    "text": "If the numerator of a fraction is \\(x\\) and denominator is \\(y\\), write the expression when \\(2\\) is added to numerator and \\(3\\) is subtracted from denominator.",
    "options": [
      {
        "text": "\\(\\frac{x + 2}{y - 3}\\)",
        "isCorrect": true
      },
      {
        "text": "\\(\\frac{x - 2}{y + 3}\\)",
        "isCorrect": false
      },
      {
        "text": "\\(\\frac{x + 3}{y - 2}\\)",
        "isCorrect": false
      },
      {
        "text": "\\(\\frac{2x}{3y}\\)",
        "isCorrect": false
      }
    ],
    "correctAnswer": "A",
    "solution": "Step 1: Original fraction is \\(\\frac{x}{y}\\).\nStep 2: Modified numerator: \\(x + 2\\); modified denominator: \\(y - 3\\).\nStep 3: The modified fraction is \\(\\frac{x + 2}{y - 3}\\).",
